public class DocumentOwnerHandler
    : AuthorizationHandler<OwnerRequirement, Document>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext ctx, OwnerRequirement req, Document doc)
    {
        if (doc.OwnerId == ctx.User.FindFirstValue(ClaimTypes.NameIdentifier))
            ctx.Succeed(req);            // no Succeed call => deny by default
        return Task.CompletedTask;
    }
}
